import { defineConfig } from "oxlint";
import { arch } from "@ktbhealth/workspace/eslint-config-arch";

// ktb architecture rules (`arch/*`) — UI preset from
// @ktbhealth/workspace's eslint-config-arch. The plugin specifier must
// name the subpath the git-tag dep exposes; the package's default
// ("eslint-plugin-arch") does not resolve for consumers installed this
// way.
const archLint = arch.ui({
	pluginSpecifier: "@ktbhealth/workspace/eslint-plugin-arch",
});

export default defineConfig({
	ignorePatterns: [
		// Generated token output — regenerated by
		// `bun run build:tokens` in packages/tailwind; never hand-edited.
		"**/generated/**",
	],
	...archLint,
});
